(7238621, 1120985, 52928, '<td valign="top">Lovely detailed capture of the wings, especially.</td>', 'Lovely detailed capture of the wings, especially.', '2014-07-08 12:21:53.000000', NULL, 1),
(7238624, 1120638, 52928, '<td valign="top">Love the colour of this photo and unusual shaped trees.</td>', 'Love the colour of this photo and unusual shaped trees.', '2014-07-08 12:23:19.000000', NULL, 1),
(7238626, 1120576, 38921, '<td valign="top">I picking up some banding in the sky and the object in the top left corner takes away from the shot.  Also, I''m not sure this is a true contre-jour shot as it look like the light is coming primarily from camera left.</td>', 'I picking up some banding in the sky and the object in the top left corner takes away from the shot.  Also, I''m not sure this is a true contre-jour shot as it look like the light is coming primarily from camera left.', '2014-07-08 12:25:01.000000', NULL, 1),
(7238628, 1120865, 52928, '<td valign="top">An interesting capture. Would have scored higher but for the loss of detail on the face of main cow.</td>', 'An interesting capture. Would have scored higher but for the loss of detail on the face of main cow.', '2014-07-08 12:26:41.000000', NULL, 1),
(7238629, 1120835, 38921, '<td valign="top">This is a neat sculpture and I like the framing you chose.  I''m not sure this can be considered a true contre-jour shot as based on the shadows the light is coming in at about a 45 degree angle from the back.</td>', 'This is a neat sculpture and I like the framing you chose.  I''m not sure this can be considered a true contre-jour shot as based on the shadows the light is coming in at about a 45 degree angle from the back.', '2014-07-08 12:28:03.000000', NULL, 1),
(7238631, 1120954, 38921, '<td valign="top">This image is underexposed.  Also it is not truly a contre-jour shot in my opinion as the light is coming in at about a 45 degree angle from the back right.</td>', 'This image is underexposed.  Also it is not truly a contre-jour shot in my opinion as the light is coming in at about a 45 degree angle from the back right.', '2014-07-08 12:29:46.000000', NULL, 1),
(7238632, 1120958, 38921, '<td valign="top">I marked this low initially and now I see I need to bump it up.  Interesting view and I like the birds.</td>', 'I marked this low initially and now I see I need to bump it up.  Interesting view and I like the birds.', '2014-07-08 12:32:59.000000', NULL, 1),
